import copy, os

class _FileHandle:
    __slots__ = ("_fd",)
    def __init__(self, fd): self._fd = fd
    def __copy__(self):
        raise TypeError("FileHandle owns an OS descriptor and cannot be copied")
    def __deepcopy__(self, memo):
        raise TypeError("FileHandle owns an OS descriptor and cannot be copied")

def open_file(path): return _FileHandle(os.open(path, os.O_RDONLY))
